import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt', sub:'Heavy',   speed:0.15, distort:1.8 },
  { score:2, emoji:'😟', label:'Dåligt',         sub:'Low',     speed:0.2,  distort:1.4 },
  { score:3, emoji:'😐', label:'Okej',           sub:'Neutral', speed:0.4,  distort:0.8 },
  { score:4, emoji:'🙂', label:'Bra',            sub:'Good',    speed:0.6,  distort:0.5 },
  { score:5, emoji:'😄', label:'Väldigt bra',    sub:'Flow',    speed:0.9,  distort:0.18 },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [hovered,  setHovered]    = useState(null);
  const [selected, setSelected]   = useState(null);
  const [note,     setNote]       = useState('');
  const [step,     setStep]       = useState('pick');

  const active = hovered ?? selected ?? 2;
  const activeMood = MOODS[active];

  const handleSave = () => {
    const m = MOODS[selected];
    addMood(m.score, m.emoji, m.label, note);
    setStep('done');
  };

  if (todayChecked && step !== 'done') return (
    <Done mood={MOODS[2]} title="Redan incheckad" sub="Kom tillbaka imorgon." setPage={setPage} />
  );
  if (step === 'done') return (
    <Done mood={MOODS[selected]} title="Sparat" sub="Bra att du checkade in." setPage={setPage} />
  );

  if (step === 'note') return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 50% 30%, rgba(60,50,100,0.14) 0%, transparent 55%)', pointerEvents:'none' }} />
      <div style={{ padding:'24px 16px', maxWidth:480, margin:'0 auto', animation:'fadeUp .5s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={200} speed={MOODS[selected].speed} distort={MOODS[selected].distort} key={selected} />
        </div>
        <div style={{ textAlign:'center', marginBottom:28 }}>
          <span style={{ fontSize:32, display:'block', marginBottom:6 }}>{MOODS[selected].emoji}</span>
          <h2 style={{ fontSize:30, fontWeight:900, letterSpacing:'-0.04em', textTransform:'uppercase', color:'#f2f0eb' }}>{MOODS[selected].label}</h2>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(242,240,235,0.3)', marginTop:5, letterSpacing:'0.14em', textTransform:'uppercase' }}>{MOODS[selected].sub}</p>
        </div>
        <div className="liq" style={{ padding:'16px 18px', marginBottom:12 }}>
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:10 }}>Notering · valfri</div>
          <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
            placeholder="Vad hände idag?"
            style={{ width:'100%', background:'transparent', border:'none', color:'#f2f0eb', fontSize:14, fontWeight:300, resize:'none', height:80, outline:'none', lineHeight:1.7 }} />
        </div>
        <button onClick={handleSave} style={{ width:'100%', padding:'14px', borderRadius:14, background:'rgba(242,240,235,0.95)', color:'#0c0c0e', fontSize:12, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.14em', textTransform:'uppercase', marginBottom:8, boxShadow:'0 4px 20px rgba(0,0,0,0.4)' }}>
          Spara →
        </button>
        <button onClick={()=>setStep('pick')} style={{ width:'100%', padding:'10px', fontSize:11, color:'rgba(242,240,235,0.3)', fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase' }}>
          ← Ändra
        </button>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 50% 25%, rgba(60,50,100,0.15) 0%, transparent 55%)', pointerEvents:'none' }} />
      <div style={{ padding:'24px 16px', position:'relative', zIndex:1 }}>

        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:6 }}>Daglig check-in</div>
        <h1 style={{ fontSize:'clamp(36px,9vw,56px)', fontWeight:900, letterSpacing:'-0.06em', lineHeight:0.86, color:'#f2f0eb', textTransform:'uppercase', marginBottom:28 }}>
          HUR<br/>MÅR DU?
        </h1>

        {/* Sphere preview — changes with hover */}
        <div style={{ display:'flex', justifyContent:'center', marginBottom:28, height:180, alignItems:'center' }}>
          <div style={{ transition:'transform .5s cubic-bezier(0.16,1,0.3,1)' }}>
            <MeshSphere size={180} speed={activeMood.speed} distort={activeMood.distort} key={active} />
          </div>
        </div>

        {/* Mood list — liquid glass rows */}
        <div style={{ display:'flex', flexDirection:'column', gap:6, marginBottom:14 }}>
          {MOODS.slice().reverse().map((m, i) => {
            const idx = 4 - i;
            const isSel = selected === idx;
            const isHov = hovered === idx;
            return (
              <button key={m.score}
                onMouseEnter={()=>setHovered(idx)}
                onMouseLeave={()=>setHovered(null)}
                onClick={()=>setSelected(idx)}
                className="liq"
                style={{ display:'flex', alignItems:'center', justifyContent:'space-between', padding:'14px 18px', borderRadius:16, background: isSel||isHov ? 'linear-gradient(135deg, rgba(255,255,255,0.13) 0%, rgba(255,255,255,0.07) 100%)' : 'linear-gradient(135deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.02) 100%)', transform: isHov&&!isSel ? 'translateX(4px)' : 'none', transition:'all .22s cubic-bezier(0.16,1,0.3,1)', border:`1px solid ${isSel ? 'rgba(255,255,255,0.18)' : 'rgba(255,255,255,0.08)'}` }}>
                <div style={{ display:'flex', alignItems:'center', gap:14 }}>
                  <span style={{ fontSize:22, transition:'transform .2s', transform: isHov||isSel ? 'scale(1.12)' : 'scale(1)' }}>{m.emoji}</span>
                  <div>
                    <div style={{ fontSize:14, fontWeight: isSel ? 700 : 400, color: isSel ? '#f2f0eb' : 'rgba(242,240,235,0.65)', letterSpacing:'-0.01em', transition:'all .2s' }}>{m.label}</div>
                    <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(242,240,235,0.28)', letterSpacing:'0.12em', textTransform:'uppercase', marginTop:2 }}>{m.sub}</div>
                  </div>
                </div>
                <span style={{ fontSize:12, color:'rgba(242,240,235,0.25)', opacity:isSel||isHov?1:0, transition:'opacity .2s' }}>→</span>
              </button>
            );
          })}
        </div>

        <button onClick={()=>setStep('note')} disabled={selected===null}
          style={{ width:'100%', padding:'14px', borderRadius:14, background:selected!==null?'rgba(242,240,235,0.95)':'rgba(255,255,255,0.07)', color:selected!==null?'#0c0c0e':'rgba(242,240,235,0.2)', fontSize:12, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.14em', textTransform:'uppercase', transition:'all .3s', boxShadow:selected!==null?'0 4px 20px rgba(0,0,0,0.4)':'none' }}>
          Fortsätt →
        </button>
      </div>
    </div>
  );
}

function Done({ mood, title, sub, setPage }) {
  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 20px', position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 50% 40%, rgba(50,60,80,0.15) 0%, transparent 55%)', pointerEvents:'none' }} />
      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={200} speed={mood.speed} distort={mood.distort} />
        </div>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:10 }}>Check-in · OK</div>
        <h2 style={{ fontSize:36, fontWeight:900, letterSpacing:'-0.05em', textTransform:'uppercase', color:'#f2f0eb', marginBottom:10 }}>{title}</h2>
        <p style={{ fontSize:14, color:'rgba(242,240,235,0.4)', marginBottom:32, fontWeight:300 }}>{sub}</p>
        <div style={{ display:'flex', gap:8, justifyContent:'center' }}>
          <button onClick={()=>setPage('history')} style={{ padding:'12px 22px', borderRadius:12, background:'rgba(242,240,235,0.95)', color:'#0c0c0e', fontSize:11, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase', boxShadow:'0 4px 20px rgba(0,0,0,0.4)' }}>Historik</button>
          <button onClick={()=>setPage('home')} className="liq" style={{ padding:'12px 22px', borderRadius:12, color:'rgba(242,240,235,0.55)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase' }}>Hem</button>
        </div>
      </div>
    </div>
  );
}
